/**
 * Wellington Dam Dive Map
 * Interactive map with bathymetry visualization and survey line overlays
 */

// ============================================
// Configuration
// ============================================

// Volume-to-Level Lookup Table (calibrated from bathymetry + survey cross-reference)
// Generated by generate_volume_lookup.py using:
// - Survey cross-reference: 84.35 GL @ 156.96m AHD
// - Full supply reference: 185 GL @ 165.5m AHD
const VOLUME_TO_LEVEL = [
    { volumeGL: 0, levelAHD: 126.0 },
    { volumeGL: 50, levelAHD: 153.8 },
    { volumeGL: 60, levelAHD: 154.7 },
    { volumeGL: 70, levelAHD: 155.7 },
    { volumeGL: 80, levelAHD: 156.6 },
    { volumeGL: 84.35, levelAHD: 156.96 },
    { volumeGL: 90, levelAHD: 157.5 },
    { volumeGL: 100, levelAHD: 158.3 },
    { volumeGL: 120, levelAHD: 159.9 },
    { volumeGL: 150, levelAHD: 162.6 },
    { volumeGL: 185, levelAHD: 165.5 },
];

/**
 * Get water level from storage volume using calibrated lookup table
 * @param {number} volumeGL - Storage volume in gigalitres
 * @returns {number} Water level in meters AHD
 */
function getWaterLevelFromVolume(volumeGL) {
    if (volumeGL <= VOLUME_TO_LEVEL[0].volumeGL) {
        return VOLUME_TO_LEVEL[0].levelAHD;
    }
    if (volumeGL >= VOLUME_TO_LEVEL[VOLUME_TO_LEVEL.length - 1].volumeGL) {
        return VOLUME_TO_LEVEL[VOLUME_TO_LEVEL.length - 1].levelAHD;
    }

    for (let i = 1; i < VOLUME_TO_LEVEL.length; i++) {
        if (volumeGL <= VOLUME_TO_LEVEL[i].volumeGL) {
            const prev = VOLUME_TO_LEVEL[i - 1];
            const curr = VOLUME_TO_LEVEL[i];
            const t = (volumeGL - prev.volumeGL) / (curr.volumeGL - prev.volumeGL);
            return prev.levelAHD + t * (curr.levelAHD - prev.levelAHD);
        }
    }
    return VOLUME_TO_LEVEL[VOLUME_TO_LEVEL.length - 1].levelAHD;
}

