// ============================================
// Depth Gradient Legend
// ============================================

function initializeDepthGradient() {
    const gradientEl = document.getElementById('depth-gradient');
    if (!gradientEl) return;

    const [minDepth, maxDepth] = getActiveDepthRange();

    // Generate CSS gradient from Turbo colormap
    const stops = [];
    for (let i = 0; i <= 10; i++) {
        const depth = (i / 10) * maxDepth;
        const [r, g, b] = getTurboColorForDepth(depth, minDepth, maxDepth);
        stops.push(`rgb(${r}, ${g}, ${b}) ${i * 10}%`);
    }

    gradientEl.style.background = `linear-gradient(to bottom, ${stops.join(', ')})`;
}

// ============================================
// Bathymetry Layers
// ============================================

/**
 * Set up color function for bathymetry layer
 * Uses dynamic water level from state
 */
function setupBathymetryColorFunction() {
    MaplibreCOGProtocol.setColorFunction(CONFIG.BATHY_COG, (pixel, color, metadata) => {
        const elevation = pixel[0];
        const waterLevel = getActiveWaterLevel();
        const [minDepth, maxDepth] = getActiveDepthRange();

        // Handle NoData values
        if (elevation === metadata.noData || elevation >= 1e5 || !Number.isFinite(elevation)) {
            color.set([0, 0, 0, 0]);
            return;
        }

        // Don't render areas above water level (not submerged)
        if (elevation > waterLevel) {
            color.set([0, 0, 0, 0]);
            return;
        }

        // Calculate depth and get color
        const depth = waterLevel - elevation;
        const [r, g, b] = getTurboColorForDepth(depth, minDepth, maxDepth);
        color.set([r, g, b, 255]);
    });
}

async function addBathymetryLayers() {
    // Set up color function (will read water level dynamically)
    setupBathymetryColorFunction();

    try {
        // Add bathymetry source and layer
        map.addSource('bathymetry-source', {
            type: 'raster',
            url: `cog://${CONFIG.BATHY_COG}`,
            tileSize: 256
        });

        map.addLayer({
            id: 'bathymetry-layer',
            type: 'raster',
            source: 'bathymetry-source',
            paint: {
                'raster-opacity': 1.0,
                'raster-resampling': 'nearest'
            },
            layout: {
                visibility: state.layerVisibility.bathymetry ? 'visible' : 'none'
            }
        });

        // Add custom WebGL hillshade layer with multiply blend mode
        // This renders on top of bathymetry and darkens shadowed areas
        state.hillshadeLayer = createMultiplyHillshadeLayer({
            id: 'hillshade-layer',
            cogUrl: CONFIG.HILLSHADE_COG,
            opacity: 1.0
        });

        map.addLayer(state.hillshadeLayer);

        console.log('Bathymetry layers added successfully');
    } catch (error) {
        console.error('Failed to add bathymetry layers:', error);
    }
}

// ============================================
// Survey Line Loading
// ============================================

async function loadSurveyLines() {
    const allFeatures = [];

    for (const filename of CONFIG.SURVEY_LINE_FILES) {
        try {
            const response = await fetch(filename);
            if (!response.ok) {
                console.warn(`Could not load ${filename}`);
                continue;
            }

            const csvText = await response.text();
            const lines = csvText.trim().split('\n');
            const headers = lines[0].split(',');

            // Find column indices
            const yIndex = headers.findIndex(h => h.trim() === 'Y');
            const xIndex = headers.findIndex(h => h.trim() === 'X');
            const elevIndex = headers.findIndex(h => h.trim() === 'Elevation');
            const markerIndex = headers.findIndex(h => h.trim() === 'Marker');

            if (yIndex === -1 || xIndex === -1) {
                console.warn(`Missing Y/X columns in ${filename}`);
                continue;
            }

            // Parse coordinates and create line
            const coordinates = [];
            const points = [];

            for (let i = 1; i < lines.length; i++) {
                const values = lines[i].split(',');
                const lat = parseFloat(values[yIndex]);
                const lng = parseFloat(values[xIndex]);
                const elevation = elevIndex !== -1 ? parseFloat(values[elevIndex]) : null;
                const marker = markerIndex !== -1 ? values[markerIndex]?.trim() : null;

                if (!isNaN(lat) && !isNaN(lng)) {
                    coordinates.push([lng, lat]);
                    points.push({
                        coord: [lng, lat],
                        elevation: elevation,  // Depth below surface (negative)
                        marker: marker
                    });
                }
            }

            if (coordinates.length >= 2) {
                // Store the survey data
                const lineKey = filename.replace('.csv', '');
                state.surveyData[lineKey] = {
                    coordinates,
                    points,
                    color: CONFIG.SURVEY_LINE_COLORS[lineKey],
                    name: CONFIG.SURVEY_LINE_NAMES[lineKey]
                };

                // Create LineString feature
                allFeatures.push({
                    type: 'Feature',
                    geometry: {
                        type: 'LineString',
                        coordinates: coordinates
                    },
                    properties: {
                        lineKey: lineKey,
                        name: CONFIG.SURVEY_LINE_NAMES[lineKey],
                        color: CONFIG.SURVEY_LINE_COLORS[lineKey],
                        pointCount: coordinates.length
                    }
                });

                console.log(`Loaded ${filename}: ${coordinates.length} points`);
            }
        } catch (error) {
            console.error(`Error loading ${filename}:`, error);
        }
    }

    // Add survey lines to map
    if (allFeatures.length > 0) {
        map.addSource('survey-lines', {
            type: 'geojson',
            data: {
                type: 'FeatureCollection',
                features: allFeatures
            }
        });

        // Build color expression
        const colorExpression = ['match', ['get', 'lineKey']];
        Object.entries(CONFIG.SURVEY_LINE_COLORS).forEach(([key, color]) => {
            colorExpression.push(key, color);
        });
        colorExpression.push('#888888');

        // Add visible line layer
        map.addLayer({
            id: 'survey-lines-layer',
            type: 'line',
            source: 'survey-lines',
            paint: {
                'line-color': colorExpression,
                'line-width': 4,
                'line-opacity': 0.9
            }
        });

        // Add hit area for easier clicking
        map.addLayer({
            id: 'survey-lines-hitarea',
            type: 'line',
            source: 'survey-lines',
            paint: {
                'line-color': '#000000',
                'line-width': 20,
                'line-opacity': 0
            }
        });
    }
}

// ============================================
// Contour Generation
// ============================================

async function initializeContourGeneration() {
    try {
        const tiff = await GeoTIFF.fromUrl(CONFIG.BATHY_COG, {
            allowFullFile: false,
            cacheSize: 100
        });

        state.geoTiffImage = await tiff.getImage();

        // Add empty contours source
        map.addSource('contours-source', {
            type: 'geojson',
            data: { type: 'FeatureCollection', features: [] }
        });

        // Add contour line layer
        map.addLayer({
            id: 'contours-layer',
            type: 'line',
            source: 'contours-source',
            paint: {
                'line-color': CONFIG.CONTOUR_COLOR,
                'line-width': [
                    'case',
                    ['==', ['%', ['get', 'depth'], 10], 0],
                    2,
                    1
                ],
                'line-opacity': 0.6
            },
            layout: {
                visibility: state.layerVisibility.contours ? 'visible' : 'none'
            },
            minzoom: Math.min(...Object.keys(CONFIG.CONTOUR_INTERVALS).map(Number))
        }, 'survey-lines-layer');

        // Add contour labels
        map.addLayer({
            id: 'contours-labels',
            type: 'symbol',
            source: 'contours-source',
            paint: {
                'text-color': CONFIG.CONTOUR_COLOR,
                'text-halo-color': '#ffffff',
                'text-halo-width': 2,
                'text-opacity': 0.9
            },
            layout: {
                'text-field': ['concat', ['get', 'depth'], 'm'],
                'text-font': ['Open Sans Regular', 'Arial Unicode MS Regular'],
                'text-size': 11,
                'symbol-placement': 'line',
                'symbol-spacing': 200,
                'text-rotation-alignment': 'map',
                'text-pitch-alignment': 'viewport',
                'text-max-angle': 30,
                'text-padding': 10,
                visibility: state.layerVisibility.contours ? 'visible' : 'none'
            },
            minzoom: Math.min(...Object.keys(CONFIG.CONTOUR_INTERVALS).map(Number))
        }, 'survey-lines-layer');

        // Generate initial contours
        if (map.getZoom() >= Math.min(...Object.keys(CONFIG.CONTOUR_INTERVALS).map(Number))) {
            await generateContoursForViewport();
        }

        // Regenerate on map movement
        map.on('moveend', debounce(generateContoursForViewport, 300));

    } catch (error) {
        console.error('Failed to initialize contour generation:', error);
    }
}

async function generateContoursForViewport() {
    if (state.isGeneratingContours || !state.geoTiffImage) return;
    if (!state.layerVisibility.contours) return;

    const zoom = Math.floor(map.getZoom());
    const minContourZoom = Math.min(...Object.keys(CONFIG.CONTOUR_INTERVALS).map(Number));
    if (zoom < minContourZoom) return;

    const bounds = map.getBounds();

    // Determine contour interval
    let interval = 10;
    for (const [zoomThreshold, int] of Object.entries(CONFIG.CONTOUR_INTERVALS).sort((a, b) => b[0] - a[0])) {
        if (zoom >= parseInt(zoomThreshold)) {
            interval = int;
            break;
        }
    }

    // Check cache
    const cacheKey = `${zoom}-${interval}-${bounds.toString()}`;
    if (state.contoursCache.has(cacheKey)) {
        map.getSource('contours-source').setData(state.contoursCache.get(cacheKey));
        return;
    }

    state.isGeneratingContours = true;
    document.getElementById('contours-loading')?.classList.add('active');

    try {
        const imageBbox = state.geoTiffImage.getBoundingBox();
        const imageWidth = state.geoTiffImage.getWidth();
        const imageHeight = state.geoTiffImage.getHeight();

        // WGS84 to Web Mercator
        const lngLatToWebMercator = (lng, lat) => {
            const x = (lng * 20037508.34) / 180;
            let y = Math.log(Math.tan(((90 + lat) * Math.PI) / 360)) / (Math.PI / 180);
            y = (y * 20037508.34) / 180;
            return [x, y];
        };

        const [minX, minY] = lngLatToWebMercator(bounds.getWest(), bounds.getSouth());
        const [maxX, maxY] = lngLatToWebMercator(bounds.getEast(), bounds.getNorth());

        const bufferX = (maxX - minX) * 0.5;
        const bufferY = (maxY - minY) * 0.5;

        // Calculate pixel window
        const left = Math.floor(((minX - bufferX - imageBbox[0]) / (imageBbox[2] - imageBbox[0])) * imageWidth);
        const right = Math.ceil(((maxX + bufferX - imageBbox[0]) / (imageBbox[2] - imageBbox[0])) * imageWidth);
        const top = Math.floor(((imageBbox[3] - (maxY + bufferY)) / (imageBbox[3] - imageBbox[1])) * imageHeight);
        const bottom = Math.ceil(((imageBbox[3] - (minY - bufferY)) / (imageBbox[3] - imageBbox[1])) * imageHeight);

        const windowLeft = Math.max(0, left);
        const windowTop = Math.max(0, top);
        const windowRight = Math.min(imageWidth, right);
        const windowBottom = Math.min(imageHeight, bottom);
        const windowWidth = windowRight - windowLeft;
        const windowHeight = windowBottom - windowTop;

        // Determine resolution
        const isMobile = globalThis.innerWidth <= 768;
        const baseResolution = isMobile ? 256 : 512;
        const targetPixels = Math.min(
            baseResolution * Math.pow(2, Math.max(0, zoom - 15)),
            isMobile ? 1024 : 2048
        );

        const aspectRatio = windowWidth / windowHeight;
        let width, height;
        if (aspectRatio > 1) {
            width = targetPixels;
            height = Math.floor(targetPixels / aspectRatio);
        } else {
            height = targetPixels;
            width = Math.floor(targetPixels * aspectRatio);
        }

        // Read elevation data
        const data = await state.geoTiffImage.readRasters({
            window: [windowLeft, windowTop, windowRight, windowBottom],
            width,
            height,
            fillValue: -9999,
            resampleMethod: 'linear'
        });

        const elevationGrid = data[0];

        // Calculate actual extent in Web Mercator
        const actualMinX = imageBbox[0] + (windowLeft / imageWidth) * (imageBbox[2] - imageBbox[0]);
        const actualMaxX = imageBbox[0] + (windowRight / imageWidth) * (imageBbox[2] - imageBbox[0]);
        const actualMaxY = imageBbox[3] - (windowTop / imageHeight) * (imageBbox[3] - imageBbox[1]);
        const actualMinY = imageBbox[3] - (windowBottom / imageHeight) * (imageBbox[3] - imageBbox[1]);

        // Generate depth contour thresholds (converted to AHD elevations)
        // Contours at depths: 5m, 10m, 15m, 20m, 25m, 30m
        // AHD = water_level - depth
        const waterLevel = getActiveWaterLevel();
        const maxContourDepth = Math.round(waterLevel - CONFIG.MIN_ELEVATION_AHD);
        const thresholds = [];
        for (let depth = interval; depth <= maxContourDepth; depth += interval) {
            const ahdLevel = waterLevel - depth;
            if (ahdLevel >= CONFIG.MIN_ELEVATION_AHD) {
                thresholds.push(ahdLevel);
            }
        }

        // Generate contours
        const contourGenerator = d3.contours()
            .size([width, height])
            .thresholds(thresholds)
            .smooth(true);

        const contourMultiPolygons = contourGenerator(elevationGrid);

        // Web Mercator to WGS84
        const webMercatorToLngLat = (x, y) => {
            const lng = (x / 20037508.34) * 180;
            let lat = (y / 20037508.34) * 180;
            lat = (180 / Math.PI) * (2 * Math.atan(Math.exp((lat * Math.PI) / 180)) - Math.PI / 2);
            return [lng, lat];
        };

        // Convert to GeoJSON features
        const features = [];
        const viewportMinX = lngLatToWebMercator(bounds.getWest(), bounds.getSouth())[0];
        const viewportMaxX = lngLatToWebMercator(bounds.getEast(), bounds.getNorth())[0];
        const viewportMinY = lngLatToWebMercator(bounds.getWest(), bounds.getSouth())[1];
        const viewportMaxY = lngLatToWebMercator(bounds.getEast(), bounds.getNorth())[1];

        for (const multiPolygon of contourMultiPolygons) {
            if (multiPolygon.coordinates.length === 0) continue;

            const ahdLevel = multiPolygon.value;
            const depth = Math.round(waterLevel - ahdLevel);

            // Skip invalid depths
            if (depth <= 0) continue;

            for (const polygon of multiPolygon.coordinates) {
                for (const ring of polygon) {
                    // Skip very small rings (noise)
                    if (ring.length < 10) continue;

                    // Transform to geographic coordinates
                    const geoCoords = ring.map(([x, y]) => {
                        const mercatorX = actualMinX + (x / width) * (actualMaxX - actualMinX);
                        const mercatorY = actualMaxY - (y / height) * (actualMaxY - actualMinY);
                        return webMercatorToLngLat(mercatorX, mercatorY);
                    });

                    // Filter contours entirely outside viewport
                    const margin = (viewportMaxX - viewportMinX) * 0.01;
                    let hasInteriorPoint = false;

                    for (const [lng, lat] of geoCoords) {
                        const [mx, my] = lngLatToWebMercator(lng, lat);
                        if (mx > viewportMinX + margin && mx < viewportMaxX - margin &&
                            my > viewportMinY + margin && my < viewportMaxY - margin) {
                            hasInteriorPoint = true;
                            break;
                        }
                    }

                    if (!hasInteriorPoint) continue;

                    features.push({
                        type: 'Feature',
                        properties: {
                            depth: depth,
                            ahdLevel: ahdLevel,
                            interval
                        },
                        geometry: {
                            type: 'LineString',
                            coordinates: geoCoords
                        }
                    });
                }
            }
        }

        const geojson = {
            type: 'FeatureCollection',
            features
        };

        if (map.getSource('contours-source')) {
            map.getSource('contours-source').setData(geojson);
        }

        // Cache
        if (state.contoursCache.size > 20) {
            const firstKey = state.contoursCache.keys().next().value;
            state.contoursCache.delete(firstKey);
        }
        state.contoursCache.set(cacheKey, geojson);

    } catch (error) {
        console.error('Failed to generate contours:', error);
    } finally {
        state.isGeneratingContours = false;
        document.getElementById('contours-loading')?.classList.remove('active');
    }
}

// ============================================
// Measure Tool
// ============================================

function initializeMeasureTool() {
    const measureBtn = document.getElementById('measure-btn');
    const clearBtn = document.getElementById('clear-btn');

    measureBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        state.measureMode = !state.measureMode;
        measureBtn.classList.toggle('active', state.measureMode);

        if (state.measureMode) {
            document.body.classList.add('measure-mode-active');
            clearBtn.style.display = 'block';
        } else {
            document.body.classList.remove('measure-mode-active');
        }

        measureBtn.blur();
    });

    clearBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        clearMeasurements();
    });

    // Add measure sources
    map.addSource('measure-line', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] }
    });

    map.addSource('measure-points', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] }
    });

    map.addLayer({
        id: 'measure-line-layer',
        type: 'line',
        source: 'measure-line',
        paint: {
            'line-color': '#0891b2',
            'line-width': 3,
            'line-dasharray': [2, 2]
        }
    });

    map.addLayer({
        id: 'measure-points-layer',
        type: 'circle',
        source: 'measure-points',
        paint: {
            'circle-radius': 6,
            'circle-color': '#0891b2',
            'circle-stroke-color': '#ffffff',
            'circle-stroke-width': 2
        }
    });
}

function clearMeasurements() {
    state.measurePoints = [];
    state.totalDistance = 0;

    document.getElementById('measure-panel').style.display = 'none';
    document.getElementById('measure-total').textContent = '0 m';
    document.getElementById('measure-items').innerHTML = '';

    map.getSource('measure-line').setData({ type: 'FeatureCollection', features: [] });
    map.getSource('measure-points').setData({ type: 'FeatureCollection', features: [] });
}

async function addMeasurePoint(lngLat) {
    const measurePanel = document.getElementById('measure-panel');
    const measureTotal = document.getElementById('measure-total');
    const measureItems = document.getElementById('measure-items');

    let distance = 0;
    let displayName = 'Start point';

    if (state.measurePoints.length > 0) {
        const lastPoint = state.measurePoints[state.measurePoints.length - 1];
        distance = haversineDistance(
            [lastPoint.lng, lastPoint.lat],
            [lngLat.lng, lngLat.lat]
        );
        displayName = `Point ${state.measurePoints.length + 1}`;
    }

    state.measurePoints.push({
        lng: lngLat.lng,
        lat: lngLat.lat,
        distance: distance
    });

    state.totalDistance += distance;

    measurePanel.style.display = 'block';
    measureTotal.textContent = formatDistance(state.totalDistance);

    const itemEl = document.createElement('div');
    itemEl.className = 'measure-item';
    itemEl.innerHTML = `
        <span class="measure-item-name">
            <span class="measure-item-dot" style="background: #0891b2;"></span>
            ${displayName}
        </span>
        <span class="measure-item-info">
            <span class="measure-item-distance">${formatDistance(distance)}</span>
        </span>
    `;
    measureItems.appendChild(itemEl);

    updateMeasureVisualization();
}

function updateMeasureVisualization() {
    const pointFeatures = state.measurePoints.map((point, index) => ({
        type: 'Feature',
        geometry: {
            type: 'Point',
            coordinates: [point.lng, point.lat]
        },
        properties: { index }
    }));

    map.getSource('measure-points').setData({
        type: 'FeatureCollection',
        features: pointFeatures
    });

    if (state.measurePoints.length >= 2) {
        const lineCoords = state.measurePoints.map(p => [p.lng, p.lat]);
        map.getSource('measure-line').setData({
            type: 'FeatureCollection',
            features: [{
                type: 'Feature',
                geometry: {
                    type: 'LineString',
                    coordinates: lineCoords
                },
                properties: {}
            }]
        });
    }
}

// ============================================
// Click Handlers
// ============================================

function initializeClickHandlers() {
    // Survey line click handler
    map.on('click', 'survey-lines-hitarea', (e) => {
        if (e.features.length === 0) return;

        const feature = e.features[0];
        const props = feature.properties;

        if (state.measureMode) {
            addMeasurePoint(e.lngLat);
        } else {
            const content = `
                <div class="segment-popup">
                    <div class="popup-title">${props.name}</div>
                    <div class="popup-row">
                        <span class="popup-label">Points</span>
                        ${props.pointCount}
                    </div>
                </div>
            `;

            if (state.activePopup) state.activePopup.remove();
            state.activePopup = new maplibregl.Popup({ closeButton: true, maxWidth: '280px' })
                .setLngLat(e.lngLat)
                .setHTML(content)
                .addTo(map);
        }
    });

    // General map click
    map.on('click', (e) => {
        if (!state.measureMode) return;

        const features = map.queryRenderedFeatures(e.point, {
            layers: ['survey-lines-hitarea']
        });

        if (features.length === 0) {
            addMeasurePoint(e.lngLat);
        }
    });

    // Cursor changes
    map.on('mouseenter', 'survey-lines-hitarea', () => {
        if (!state.measureMode) {
            map.getCanvas().style.cursor = 'pointer';
        }
    });

    map.on('mouseleave', 'survey-lines-hitarea', () => {
        if (!state.measureMode) {
            map.getCanvas().style.cursor = '';
        }
    });
}

// ============================================
// Layer Controls
// ============================================

function initializeLayerControls() {
    const layerControls = document.querySelectorAll('.layer-control[data-layer]');

    layerControls.forEach(control => {
        const layerId = control.dataset.layer;
        const checkbox = control.querySelector('input[type="checkbox"]');

        checkbox.addEventListener('change', () => {
            state.layerVisibility[layerId] = checkbox.checked;
            const visibility = checkbox.checked ? 'visible' : 'none';

            if (layerId === 'bathymetry') {
                if (map.getLayer('bathymetry-layer')) {
                    map.setLayoutProperty('bathymetry-layer', 'visibility', visibility);
                }
                // Custom hillshade layer - use opacity for visibility control
                if (state.hillshadeLayer) {
                    state.hillshadeLayer.setOpacity(checkbox.checked ? 1.0 : 0.0);
                    map.triggerRepaint();
                }
            } else if (layerId === 'contours') {
                if (map.getLayer('contours-layer')) {
                    map.setLayoutProperty('contours-layer', 'visibility', visibility);
                }
                if (map.getLayer('contours-labels')) {
                    map.setLayoutProperty('contours-labels', 'visibility', visibility);
                }
                if (checkbox.checked) {
                    generateContoursForViewport();
                }
            }
        });
    });
}

// ============================================
// Mobile Toggle
// ============================================

function initializeMobileToggle() {
    const titleCard = document.querySelector('.title-card');
    const legend = document.querySelector('.legend');
    const legendToggle = document.getElementById('legend-toggle');

    titleCard.addEventListener('click', (e) => {
        if (globalThis.innerWidth <= 768) {
            if (e.target.tagName !== 'A') {
                titleCard.classList.toggle('expanded');
            }
        }
    });

    if (legendToggle && legend) {
        legendToggle.addEventListener('click', (e) => {
            e.stopPropagation();
            e.preventDefault();
            legend.classList.toggle('collapsed');

            const isCollapsed = legend.classList.contains('collapsed');
            localStorage.setItem('legendCollapsed', isCollapsed ? 'true' : 'false');
        });

        if (globalThis.innerWidth <= 768) {
            const savedState = localStorage.getItem('legendCollapsed');
            if (savedState === 'true') {
                legend.classList.add('collapsed');
            }
        }
    }
}

// ============================================
// Legend Zoom to Survey Line
// ============================================

function initializeLegendToggles() {
    const colorItems = document.querySelectorAll('.color-item[data-line]');

    colorItems.forEach(item => {
        item.addEventListener('click', () => {
            const lineKey = item.dataset.line;
            const surveyLine = state.surveyData[lineKey];

            if (surveyLine && surveyLine.coordinates.length > 0) {
                const lngs = surveyLine.coordinates.map(c => c[0]);
                const lats = surveyLine.coordinates.map(c => c[1]);

                const bounds = [
                    [Math.min(...lngs), Math.min(...lats)],
                    [Math.max(...lngs), Math.max(...lats)]
                ];

                const isMobile = globalThis.innerWidth <= 768;
                const padding = isMobile
                    ? { top: 120, bottom: 250, left: 50, right: 50 }
                    : { top: 100, bottom: 100, left: 400, right: 100 };

                map.fitBounds(bounds, {
                    padding: padding,
                    maxZoom: 17,
                    duration: 1000
                });

                colorItems.forEach(ci => ci.classList.remove('selected'));
                item.classList.add('selected');
            }
        });
    });
}

// ============================================
// Context Menu
// ============================================

map.on('contextmenu', (e) => {
    const existing = document.getElementById('context-menu');
    if (existing) existing.remove();

    const { lng, lat } = e.lngLat;
    const coords = formatCoordinates(lng, lat);

    const menu = document.createElement('div');
    menu.id = 'context-menu';
    menu.className = 'context-menu';
    menu.style.left = `${e.point.x}px`;
    menu.style.top = `${e.point.y}px`;

    menu.innerHTML = `
        <div class="context-menu-item" id="copy-dd">
            <span>Copy Decimal Degrees</span>
            <span style="opacity: 0.5; margin-left: 12px; font-size: 0.7rem;">${coords.gmaps}</span>
        </div>
        <div class="context-menu-separator"></div>
        <div class="context-menu-item" id="copy-dm">
            <span>Copy Decimal Minutes</span>
            <span style="opacity: 0.5; margin-left: 12px; font-size: 0.7rem;">${coords.display}</span>
        </div>
        <div class="context-menu-separator"></div>
        <div class="context-menu-item" id="copy-link">
            <span>Copy Link</span>
        </div>
    `;

    document.body.appendChild(menu);

    document.getElementById('copy-dd').addEventListener('click', () => {
        navigator.clipboard.writeText(coords.gmaps);
        menu.remove();
    });

    document.getElementById('copy-dm').addEventListener('click', () => {
        navigator.clipboard.writeText(coords.display);
        menu.remove();
    });

    document.getElementById('copy-link').addEventListener('click', () => {
        const url = `${globalThis.location.origin}${globalThis.location.pathname}#${lat.toFixed(6)},${lng.toFixed(6)}`;
        navigator.clipboard.writeText(url);
        menu.remove();
    });

    const closeMenu = () => {
        menu.remove();
        document.removeEventListener('click', closeMenu);
    };
    setTimeout(() => document.addEventListener('click', closeMenu), 100);
});

// ============================================
// Water Level Display
// ============================================

function updateWaterLevelDisplay() {
    const storageGL = getActiveStorageGL();
    const waterLevel = getActiveWaterLevel();
    const [, maxDepth] = getActiveDepthRange();

    // Update water level note
    const noteEl = document.getElementById('water-level-note');
    if (noteEl) {
        if (state.useCurrentLevel) {
            noteEl.textContent = `Water level: ~${waterLevel.toFixed(1)}m AHD (${storageGL} GL)`;
            noteEl.title = `Current level from Water Corporation (${CONFIG.WATER_LEVEL_DATE})`;
        } else {
            noteEl.textContent = `Water level: ~${waterLevel.toFixed(1)}m AHD (${storageGL} GL)`;
            noteEl.title = 'Custom water level (drag slider to adjust)';
        }
    }

    // Update depth labels based on current range
    const depthLabelsEl = document.querySelector('.depth-labels');
    if (depthLabelsEl) {
        const midDepth = Math.round(maxDepth / 2);
        depthLabelsEl.innerHTML = `<span>0m</span><span>${midDepth}m</span><span>${maxDepth}m</span>`;
    }

    // Update slider value display
    const sliderValueEl = document.getElementById('water-level-value');
    if (sliderValueEl) {
        sliderValueEl.textContent = `${Math.round(storageGL)} GL`;
    }

    // Update depth gradient
    initializeDepthGradient();
}

/**
 * Refresh bathymetry tiles after water level change
 */
function refreshBathymetryTiles() {
    // Force reload by removing and re-adding the source
    // This is needed because the COG protocol caches colored tiles
    const source = map.getSource('bathymetry-source');
    if (source) {
        const visibility = map.getLayoutProperty('bathymetry-layer', 'visibility');

        // Remove layer and source
        map.removeLayer('bathymetry-layer');
        map.removeSource('bathymetry-source');

        // Re-add source and layer
        map.addSource('bathymetry-source', {
            type: 'raster',
            url: `cog://${CONFIG.BATHY_COG}`,
            tileSize: 256
        });

        map.addLayer({
            id: 'bathymetry-layer',
            type: 'raster',
            source: 'bathymetry-source',
            paint: {
                'raster-opacity': 1.0,
                'raster-resampling': 'nearest'
            },
            layout: {
                visibility: visibility
            }
        }, 'hillshade-layer'); // Insert before hillshade
    }

    map.triggerRepaint();

    // Clear contour cache since depths have changed
    state.contoursCache.clear();
}

/**
 * Handle water level change from slider or checkbox
 */
function onWaterLevelChange() {
    // Update UI elements
    updateWaterLevelDisplay();

    // Refresh bathymetry visualization
    refreshBathymetryTiles();

    // Regenerate contours for current view
    if (state.geoTiffImage && state.layerVisibility.contours) {
        generateContoursForViewport();
    }
}

/**
 * Initialize water level slider controls
 */
function initializeWaterLevelControls() {
    const slider = document.getElementById('water-level-slider');
    const lockCheckbox = document.getElementById('water-level-lock');
    const currentLevelLabel = document.getElementById('current-level-label');

    if (!slider || !lockCheckbox) return;

    // Set initial values
    slider.value = Math.round(CONFIG.CURRENT_STORAGE_GL);
    slider.disabled = state.useCurrentLevel;
    if (currentLevelLabel) {
        currentLevelLabel.textContent = `${CONFIG.CURRENT_STORAGE_GL} GL`;
    }

    // Slider input handler (while dragging)
    slider.addEventListener('input', () => {
        state.customStorageGL = parseFloat(slider.value);
        updateWaterLevelDisplay();
    });

    // Slider change handler (on release) - do the expensive refresh
    slider.addEventListener('change', () => {
        state.customStorageGL = parseFloat(slider.value);
        onWaterLevelChange();
    });

    // Checkbox handler
    lockCheckbox.addEventListener('change', () => {
        state.useCurrentLevel = lockCheckbox.checked;
        slider.disabled = state.useCurrentLevel;

        if (state.useCurrentLevel) {
            // Reset slider to current level
            slider.value = Math.round(CONFIG.CURRENT_STORAGE_GL);
        }

        onWaterLevelChange();
    });
}

// ============================================
// Map Load Handler
// ============================================

map.on('load', async () => {
    try {
        // Initialize water level controls first
        initializeWaterLevelControls();

        // Initialize depth gradient legend
        initializeDepthGradient();

        // Update water level display
        updateWaterLevelDisplay();

        // Add bathymetry layers
        await addBathymetryLayers();

        // Load survey lines
        await loadSurveyLines();

        // Initialize contour generation
        await initializeContourGeneration();

        // Initialize UI handlers
        initializeMeasureTool();
        initializeLayerControls();
        initializeClickHandlers();
        initializeLegendToggles();
        initializeMobileToggle();

        // Hide loading overlay
        document.getElementById('loading').classList.add('hidden');

    } catch (error) {
        console.error('Error loading map:', error);
        document.getElementById('loading-text').textContent = 'Error loading map';
    }
});
